#include <bits/stdc++.h>
using namespace std;

class Solution {public:int minimumCardPickup(vector<int>& cards){unordered_map<int,int> last;int ans=INT_MAX;for(int i=0;i<(int)cards.size();++i){if(last.count(cards[i]))ans=min(ans,i-last[cards[i]]+1);last[cards[i]]=i;}return ans==INT_MAX?-1:ans;} };
